# views.py landing:
def landing(req):
    if req.user.is_authenticated:
        return redirect('dashboard')
    workshops = [{'name': w.name, 'slug': w.slug}
                 for w in Workshop.objects.filter(subscription_expires__gte=date.today()).order_by('name')]
    return render(req, 'calc/landing.html', {'workshops': workshops})
