# استخراج نص الفقرات (بلا تكرار):
function Get-ParaText($p) {
  $sb = [System.Text.StringBuilder]::new()
  foreach ($r in $p.SelectNodes(".//*[local-name()='t']")) { [void]$sb.Append($r.InnerText) }
  return $sb.ToString()
}
